export const INITIAL_PRODUCTS: Product[] = RAW_PRODUCTS_DATA.map((item, idx) => {
  const code = item.product_name_eng.replace(/[^A-Za-z0-9]/g, '').substring(0, 4).toUpperCase() || 'ITEM';
  const sku = `${code}-${String(item.serial).padStart(3, '0')}`;
  const status = calculateStatus(item.stock, item.reorder, 500);

  return {
    id: `prod-tag-${item.serial}`,
    serial: item.serial,
    sku,
    name: item.product_name_eng,
    product_name_eng: item.product_name_eng,
    product_name_jp: item.product_name_jp,
    weight_unit: item.weight_unit,
    tax_rate: item.tax_rate,
    price_without_tax: item.price_without_tax,
    price_with_tax: item.price_with_tax,
    origin: item.origin,
    folderId: item.folderId,
    category: item.category,
    description: `${item.product_name_jp} (${item.origin}) - Spec: ${item.weight_unit || 'Standard'}, Tax: ${item.tax_rate}%`,
    unitCost: Math.round(item.price_without_tax * 0.7),
    sellingPrice: item.price_with_tax,
    stockQuantity: item.stock,
    reorderPoint: item.reorder,
    maxCapacity: Math.max(200, item.stock * 3),
    unit: 'pcs',
    location: `Aisle ${(item.serial % 8) + 1} · Shelf ${String.fromCharCode(65 + (item.serial % 4))}`,
    supplier: item.origin === 'UNKNOWN' ? 'Wholesale Partner' : `${item.origin} Direct Distribution`,
    leadTimeDays: item.origin === 'JAPAN' ? 3 : 14,
    lastRestocked: '2026-09-15',
    updatedAt: '2026-09-24',
    status,
  };
});

